// encodeCursor signs the cursor with an HMAC and renders it as base64rawurl.
func encodeCursor(c pageCursor) string {
	payload, _ := json.Marshal(c)
	mac := hmac.New(sha256.New, cursorSecret)
	mac.Write(payload)
	token := append(mac.Sum(nil), payload...)
	return base64.RawURLEncoding.EncodeToString(token)
}

// decodeCursor verifies the signature and parses the cursor.
func decodeCursor(raw string) (pageCursor, error) {
	token, err := base64.RawURLEncoding.DecodeString(strings.TrimSpace(raw))
	if err != nil || len(token) <= sha256.Size {
		return pageCursor{}, errors.New("invalid cursor")
	}
	signature, payload := token[:sha256.Size], token[sha256.Size:]
	mac := hmac.New(sha256.New, cursorSecret)
	mac.Write(payload)
	if !hmac.Equal(signature, mac.Sum(nil)) {
		return pageCursor{}, errors.New("invalid cursor")
	}
	var cursor pageCursor
	if err := json.Unmarshal(payload, &cursor); err != nil {
		return pageCursor{}, errors.New("invalid cursor")
	}
	return cursor, nil
}

// cursorQueryKey identifies the filter a cursor was issued under, so a cursor
// cannot be reused with different from/to parameters.
func cursorQueryKey(c pageCursor) string {
	return c.From.UTC().Format(time.RFC3339Nano) + "|" + c.To.UTC().Format(time.RFC3339Nano)
}

// encodeInt64 is only used by tests that want stable binary fixtures.
func encodeInt64(value int64) []byte {
	return binary.BigEndian.AppendUint64(nil, uint64(value))
}

