// Replay validates and commits a batch atomically. It returns
// ErrDeviceNotFound for an unknown device and ErrBatchConflict when any sample
// clashes with an existing eventId or the batchId was previously committed with
// different ordered content; in either conflict case no state changes.
func (s *Store) Replay(id, batchID string, samples []Sample) (ReplayReceipt, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	state, ok := s.devices[id]
	if !ok {
		return ReplayReceipt{}, ErrDeviceNotFound
	}

	if previous, exists := state.batches[batchID]; exists {
		if !sameOrderedSamples(previous.samples, samples) {
			return ReplayReceipt{}, ErrBatchConflict
		}
		return s.replayReceipt(state, batchID, samples), nil
	}

