			}{sample, sequence, true}
			continue
		}
		planned[i] = struct {
			sample   Sample
			sequence int64
			dup      bool
		}{sample, nextSequence, false}
		nextSequence++
	}

	// Commit: append new samples in array order.
	lastNew := -1
	for i, entry := range planned {
		if entry.dup {
			continue
		}
		state.events = append(state.events, Event{
			Sequence:   entry.sequence,
			ObservedAt: entry.sample.ObservedAt,
			Values:     cloneTelemetry(entry.sample.Values),
		})
		state.byEvent[entry.sample.EventID] = entry.sequence
		lastNew = i
	}

	committed := make([]Sample, len(samples))
	copy(committed, samples)
	for i := range committed {
		committed[i].Values = cloneTelemetry(samples[i].Values)
	}
	state.batches[batchID] = storedBatch{samples: committed}

	if lastNew >= 0 {
		now := s.now().UTC()
		state.device.LastSeenAt = now
		state.device.LastTelemetry = cloneTelemetry(samples[lastNew].Values)
	}
	return s.replayReceipt(state, batchID, samples), nil
}

func (s *Store) replayReceipt(state *deviceState, batchID string, samples []Sample) ReplayReceipt {
	receipt := ReplayReceipt{BatchID: batchID, SampleStatus: make([]SampleStatus, 0, len(samples))}
	for _, sample := range samples {
		sequence := state.byEvent[sample.EventID]
		existing := state.events[sequence-1]
		dup := sameInstant(existing.ObservedAt, sample.ObservedAt) && sameValues(existing.Values, sample.Values)
		receipt.SampleStatus = append(receipt.SampleStatus, SampleStatus{
			EventID:   sample.EventID,
			Sequence:  sequence,
			Duplicate: dup,
		})
		if dup {
			receipt.Duplicate++
		} else {
			receipt.NewCount++
		}
	}
	return receipt
}

// History returns one page of a device's event history. afterSeq is the last
// sequence already returned (0 for the first page); limit caps the page size.
// The returned highWater is the largest sequence visible at query time and
// bounds subsequent pages, so concurrent writes cannot skip or duplicate rows.
func (s *Store) History(id string, filter HistoryFilter, afterSeq int64, limit int) (events []Event, highWater int64, err error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	state, ok := s.devices[id]
	if !ok {
		return nil, 0, ErrDeviceNotFound
	}
	highWater = int64(len(state.events))
	start := afterSeq // events are 1-indexed; index afterSeq is the first candidate
	end := highWater
	if end-start > int64(limit) {
		end = start + int64(limit)
	}
	events = make([]Event, 0, end-start)
	for index := start; index < end; index++ {
		event := state.events[index]
		if !filter.From.IsZero() && event.ObservedAt.Before(filter.From) {
			continue
		}
		if !filter.To.IsZero() && event.ObservedAt.After(filter.To) {
			continue
		}
		events = append(events, cloneEvent(event))
	}
	return events, highWater, nil
}

func (s *Store) Snapshot() []Device {
	s.mu.RLock()
	defer s.mu.RUnlock()
	result := make([]Device, 0, len(s.devices))
	for _, state := range s.devices {
		result = append(result, cloneDevice(state.device))
	}
	sort.Slice(result, func(i, j int) bool { return result[i].ID < result[j].ID })
	return result
}

func cloneDevice(device Device) Device {
	device.LastTelemetry = cloneTelemetry(device.LastTelemetry)
	return device
}

func cloneEvent(event Event) Event {
	event.Values = cloneTelemetry(event.Values)
	return event
}

func cloneTelemetry(values map[string]float64) map[string]float64 {
	if values == nil {
		return nil
	}
	cloned := make(map[string]float64, len(values))
	for key, value := range values {
		cloned[key] = value
	}
	return cloned
}

// sameInstant compares times as UTC instants.
func sameInstant(a, b time.Time) bool {
	return a.UTC().Equal(b.UTC())
}

// sameValues compares metric maps by key and value.
func sameValues(a, b map[string]float64) bool {
	if len(a) != len(b) {
		return false
	}
	for key, value := range a {
		other, ok := b[key]
		if !ok || value != other {
			return false
		}
	}
	return true
}

// sameOrderedSamples reports whether two batches carry the same samples in the
// same order, compared as UTC instants and key/value maps.
func sameOrderedSamples(a, b []Sample) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i].EventID != b[i].EventID ||
			!sameInstant(a[i].ObservedAt, b[i].ObservedAt) ||
			!sameValues(a[i].Values, b[i].Values) {
			return false
		}
	}
	return true
}

