	if raw := strings.TrimSpace(query.Get("limit")); raw != "" {
		value, err := strconv.Atoi(raw)
		if err != nil || value < 1 || value > 100 {
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "limit must be between 1 and 100"})
			return
		}
		limit = value
	}

	var afterSeq, highWater int64
	rawCursor := strings.TrimSpace(query.Get("cursor"))
	if rawCursor != "" {
		cursor, err := decodeCursor(rawCursor)
		if err != nil || cursor.DeviceID != id ||
			!cursor.From.Equal(filter.From) || !cursor.To.Equal(filter.To) {
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid cursor"})
			return
		}
		afterSeq, highWater = cursor.LastSeq, cursor.HighWater
	}

	events, currentHighWater, err := h.store.History(id, filter, afterSeq, highWater, limit)
	if errors.Is(err, ErrDeviceNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	if highWater == 0 {
		highWater = currentHighWater
	}

	nextCursor := ""
	if len(events) > 0 {
		lastSeq := events[len(events)-1].Sequence
		if lastSeq < highWater {
			nextCursor = encodeCursor(pageCursor{
				DeviceID:  id,
				From:      filter.From,
				To:        filter.To,
				HighWater: highWater,
				LastSeq:   lastSeq,
			})
		}
	}

	writeJSON(w, http.StatusOK, map[string]any{
		"deviceId":   id,
		"events":     events,
		"nextCursor": nextCursor,
	})
}

func (h *handler) snapshot(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, map[string]any{"devices": h.store.Snapshot()})
}

func hasBlankKey(values map[string]float64) bool {
	for key := range values {
		if strings.TrimSpace(key) == "" {
			return true
		}
	}
	return false
}

func finiteValues(values map[string]float64) bool {
	for _, value := range values {
		if math.IsNaN(value) || math.IsInf(value, 0) {
			return false
		}
	}
	return true
}

