166				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "limit must be between 1 and 100"})
167				return
168			}
169			limit = value
170		}
171	
172		var afterSeq, highWater int64
173		rawCursor := strings.TrimSpace(query.Get("cursor"))
174		if rawCursor != "" {
175			cursor, err := decodeCursor(rawCursor)
176			if err != nil || cursor.DeviceID != id ||
177				!cursor.From.Equal(filter.From) || !cursor.To.Equal(filter.To) {
178				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid cursor"})
179				return
180			}
