1	package fleet
2	
3	import (
4		"errors"
5		"sort"
6		"sync"
7		"time"
8	)
9	
10	var (
11		ErrDeviceNotFound = errors.New("device not found")
12		ErrBatchConflict  = errors.New("batch conflicts with stored events")
13	)
14	
15	type Device struct {
16		ID            string             `json:"id"`
17		Site          string             `json:"site"`
18		RegisteredAt  time.Time          `json:"registeredAt"`
19		LastSeenAt    time.Time          `json:"lastSeenAt"`
20		LastTelemetry map[string]float64 `json:"lastTelemetry,omitempty"`
21	}
22	
23	// Event is a single telemetry sample retained in a device's history.
24	type Event struct {
25		Sequence   int64              `json:"sequence"`
26		ObservedAt time.Time          `json:"observedAt"`
27		Values     map[string]float64 `json:"values"`
28	}
29	
30	// Sample is one replayed sample, decoded from the replay request body.
31	type Sample struct {
32		EventID    string
33		ObservedAt time.Time
34		Values     map[string]float64
35	}
36	
37	// ReplayReceipt summarises the outcome of a replay batch.
38	type ReplayReceipt struct {
39		BatchID      string         `json:"batchId"`
40		NewCount     int            `json:"newCount"`
41		Duplicate    int            `json:"duplicateCount"`
42		SampleStatus []SampleStatus `json:"samples"`
43	}
44	
45	// SampleStatus reports the history sequence assigned to (or reused by) a sample.
46	type SampleStatus struct {
47		EventID   string `json:"eventId"`
48		Sequence  int64  `json:"sequence"`
49		Duplicate bool   `json:"duplicate"`
50	}
51	
52	// HistoryFilter narrows a history query by observed-time range. Zero times mean
53	// the bound is open.
54	type HistoryFilter struct {
55		From time.Time
56		To   time.Time
57	}
58	
59	// HistoryPage is one page of device history.
60	type HistoryPage struct {
61		DeviceID   string  `json:"deviceId"`
62		Events     []Event `json:"events"`
63		NextCursor string  `json:"nextCursor"`
64	}
65	
66	// StoredBatch records the ordered samples an accepted batchId committed, so a
67	// repeated batchId can be checked for identical content.
68	type storedBatch struct {
69		samples []Sample
70	}
71	
72	type deviceState struct {
73		device  Device
74		events  []Event            // history ordered by sequence (sequence = index + 1)
75		byEvent map[string]int64   // eventId -> sequence
76		batches map[string]storedBatch
77	}
78	
79	type Store struct {
80		mu      sync.RWMutex
81		devices map[string]*deviceState
82		now     func() time.Time
83	}
84	
85	func NewStore() *Store {
86		return &Store{devices: make(map[string]*deviceState), now: time.Now}
87	}
88	
89	func (s *Store) Register(id, site string) (Device, bool) {
90		s.mu.Lock()
91		defer s.mu.Unlock()
92		if state, ok := s.devices[id]; ok {
93			return cloneDevice(state.device), false
94		}
95		now := s.now().UTC()
96		device := Device{ID: id, Site: site, RegisteredAt: now, LastSeenAt: now}
97		s.devices[id] = &deviceState{
98			device:  device,
99			byEvent: make(map[string]int64),
100			batches: make(map[string]storedBatch),
101		}
102		return cloneDevice(device), true
103	}
104	
105	// RecordTelemetry stores a live telemetry sample in the device history. The
106	// sample has no caller-supplied eventId, so it is never a replay duplicate; its
107	// observed time is the server receive time.
108	func (s *Store) RecordTelemetry(id string, values map[string]float64) (Device, error) {
109		s.mu.Lock()
110		defer s.mu.Unlock()
111		state, ok := s.devices[id]
112		if !ok {
113			return Device{}, ErrDeviceNotFound
114		}
115		now := s.now().UTC()
116		state.events = append(state.events, Event{
117			Sequence:   int64(len(state.events)) + 1,
118			ObservedAt: now,
119			Values:     cloneTelemetry(values),
120		})
121		state.device.LastSeenAt = now
122		state.device.LastTelemetry = cloneTelemetry(values)
123		return cloneDevice(state.device), nil
124	}
125	
126	// Replay validates and commits a batch atomically. repeat is true when the
127	// batchId was already committed with identical content and the first receipt
128	// is returned unchanged. It returns ErrDeviceNotFound for an unknown device and
129	// ErrBatchConflict when any sample clashes with an existing eventId or the
130	// batchId was previously committed with different ordered content; in either
131	// conflict case no state changes.
132	func (s *Store) Replay(id, batchID string, samples []Sample) (receipt ReplayReceipt, repeat bool, err error) {
133		s.mu.Lock()
134		defer s.mu.Unlock()
135		state, ok := s.devices[id]
136		if !ok {
137			return ReplayReceipt{}, false, ErrDeviceNotFound
138		}
139	
140		if previous, exists := state.batches[batchID]; exists {
141			if !sameOrderedSamples(previous.samples, samples) {
142				return ReplayReceipt{}, false, ErrBatchConflict
143			}
144			return s.replayReceipt(state, batchID, samples), true, nil
145		}
146	
147		// Validate every sample against committed history before appending so a
148		// conflict rolls back without leaving sequences, events or receipts.
149		planned := make([]struct {
150			sample   Sample
151			sequence int64
152			dup      bool
153		}, len(samples))
154		nextSequence := int64(len(state.events)) + 1
155		for i, sample := range samples {
156			if sequence, seen := state.byEvent[sample.EventID]; seen {
157				existing := state.events[sequence-1]
158				if !sameInstant(existing.ObservedAt, sample.ObservedAt) ||
159					!sameValues(existing.Values, sample.Values) {
160					return ReplayReceipt{}, false, ErrBatchConflict
161				}
162				planned[i] = struct {
163					sample   Sample
164					sequence int64
165					dup      bool
166				}{sample, sequence, true}
167				continue
168			}
169			planned[i] = struct {
170				sample   Sample
171				sequence int64
172				dup      bool
173			}{sample, nextSequence, false}
174			nextSequence++
175		}
176	
177		// Commit: append new samples in array order.
178		lastNew := -1
179		for i, entry := range planned {
180			if entry.dup {
181				continue
182			}
183			state.events = append(state.events, Event{
184				Sequence:   entry.sequence,
185				ObservedAt: entry.sample.ObservedAt,
186				Values:     cloneTelemetry(entry.sample.Values),
187			})
188			state.byEvent[entry.sample.EventID] = entry.sequence
189			lastNew = i
190		}
191	
192		committed := make([]Sample, len(samples))
193		copy(committed, samples)
194		for i := range committed {
195			committed[i].Values = cloneTelemetry(samples[i].Values)
196		}
197		state.batches[batchID] = storedBatch{samples: committed}
198	
199		if lastNew >= 0 {
200			now := s.now().UTC()
201			state.device.LastSeenAt = now
202			state.device.LastTelemetry = cloneTelemetry(samples[lastNew].Values)
203		}
204		return s.replayReceipt(state, batchID, samples), false, nil
205	}
206	
207	func (s *Store) replayReceipt(state *deviceState, batchID string, samples []Sample) ReplayReceipt {
208		receipt := ReplayReceipt{BatchID: batchID, SampleStatus: make([]SampleStatus, 0, len(samples))}
209		for _, sample := range samples {
210			sequence := state.byEvent[sample.EventID]
211			existing := state.events[sequence-1]
212			dup := sameInstant(existing.ObservedAt, sample.ObservedAt) && sameValues(existing.Values, sample.Values)
213			receipt.SampleStatus = append(receipt.SampleStatus, SampleStatus{
214				EventID:   sample.EventID,
215				Sequence:  sequence,
216				Duplicate: dup,
217			})
218			if dup {
219				receipt.Duplicate++
220			} else {
221				receipt.NewCount++
222			}
223		}
224		return receipt
225	}
226	
227	// History returns one page of a device's event history. afterSeq is the last
228	// sequence already returned (0 for the first page); limit caps the page size.
229	// bound pins the scan to sequences no larger than bound; a zero bound means
230	// "current maximum", which is then returned so callers can pin subsequent
231	// pages. Concurrent writes therefore cannot skip or duplicate rows within a
232	// paged walk.
233	func (s *Store) History(id string, filter HistoryFilter, afterSeq, bound int64, limit int) (events []Event, appliedBound int64, hasMore bool, err error) {
234		s.mu.RLock()
235		defer s.mu.RUnlock()
236		state, ok := s.devices[id]
237		if !ok {
238			return nil, 0, false, ErrDeviceNotFound
239		}
240		highWater := int64(len(state.events))
241		if bound == 0 {
242			bound = highWater
243		}
244		events = make([]Event, 0, limit)
245		for index := afterSeq; index < bound; index++ {
246			event := state.events[index]
247			if !filter.From.IsZero() && event.ObservedAt.Before(filter.From) {
248				continue
249			}
250			if !filter.To.IsZero() && event.ObservedAt.After(filter.To) {
251				continue
252			}
253			if len(events) < limit {
254				events = append(events, cloneEvent(event))
255				continue
256			}
257			// A match beyond the filled page means another page exists even if the
258			// returned page is short due to non-matching rows.
259			return events, bound, true, nil
260		}
261		return events, bound, false, nil
262	}
263	
264	func (s *Store) Snapshot() []Device {
265		s.mu.RLock()
266		defer s.mu.RUnlock()
267		result := make([]Device, 0, len(s.devices))
268		for _, state := range s.devices {
269			result = append(result, cloneDevice(state.device))
270		}
271		sort.Slice(result, func(i, j int) bool { return result[i].ID < result[j].ID })
272		return result
273	}
