			Sequence:   entry.sequence,
			ObservedAt: entry.sample.ObservedAt,
			Values:     cloneTelemetry(entry.sample.Values),
		})
		state.byEvent[entry.sample.EventID] = entry.sequence
		lastNew = i
	}

