	receipt.SampleStatus = append([]SampleStatus(nil), receipt.SampleStatus...)
	return receipt
}

// History returns one page of a device's event history. afterSeq is the last
// sequence already returned (0 for the first page); limit caps the page size.
// bound pins the scan to sequences no larger than bound; a zero bound means
// "current maximum", which is then returned so callers can pin subsequent
// pages. Concurrent writes therefore cannot skip or duplicate rows within a
// paged walk.
func (s *Store) History(id string, filter HistoryFilter, afterSeq, bound int64, limit int) (events []Event, appliedBound int64, hasMore bool, err error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	state, ok := s.devices[id]
	if !ok {
		return nil, 0, false, ErrDeviceNotFound
	}
	highWater := int64(len(state.events))
	if bound == 0 {
		bound = highWater
	}
	events = make([]Event, 0, limit)
	for index := afterSeq; index < bound; index++ {
		event := state.events[index]
		if !filter.From.IsZero() && event.ObservedAt.Before(filter.From) {
			continue
		}
		if !filter.To.IsZero() && event.ObservedAt.After(filter.To) {
			continue
		}
		if len(events) < limit {
			events = append(events, cloneEvent(event))
			continue
		}
		// A match beyond the filled page means another page exists even if the
		// returned page is short due to non-matching rows.
		return events, bound, true, nil
	}
	return events, bound, false, nil
}

func (s *Store) Snapshot() []Device {
	s.mu.RLock()
	defer s.mu.RUnlock()
	result := make([]Device, 0, len(s.devices))
	for _, state := range s.devices {
		result = append(result, cloneDevice(state.device))
	}
	sort.Slice(result, func(i, j int) bool { return result[i].ID < result[j].ID })
	return result
}

func cloneDevice(device Device) Device {
	device.LastTelemetry = cloneTelemetry(device.LastTelemetry)
	return device
}

func cloneEvent(event Event) Event {
	event.Values = cloneTelemetry(event.Values)
	return event
}

func cloneTelemetry(values map[string]float64) map[string]float64 {
	if values == nil {
		return nil
	}
	cloned := make(map[string]float64, len(values))
	for key, value := range values {
		cloned[key] = value
	}
	return cloned
}

// sameInstant compares times as UTC instants.
func sameInstant(a, b time.Time) bool {
	return a.UTC().Equal(b.UTC())
}

// sameValues compares metric maps by key and value.
func sameValues(a, b map[string]float64) bool {
	if len(a) != len(b) {
		return false
	}
	for key, value := range a {
		other, ok := b[key]
		if !ok || value != other {
			return false
		}
	}
	return true
}

// sameOrderedSamples reports whether two batches carry the same samples in the
// same order, compared as UTC instants and key/value maps.
func sameOrderedSamples(a, b []Sample) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i].EventID != b[i].EventID ||
			!sameInstant(a[i].ObservedAt, b[i].ObservedAt) ||
			!sameValues(a[i].Values, b[i].Values) {
			return false
		}
	}
	return true
}

