// History returns one page of a device's event history. afterSeq is the last
// sequence already returned (0 for the first page); limit caps the page size.
// bound pins the scan to sequences no larger than bound; a zero bound means
// "current maximum", which is then returned so callers can pin subsequent
// pages. Concurrent writes therefore cannot skip or duplicate rows within a
// paged walk.
func (s *Store) History(id string, filter HistoryFilter, afterSeq, bound int64, limit int) (events []Event, appliedBound int64, hasMore bool, err error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	state, ok := s.devices[id]
	if !ok {
		return nil, 0, false, ErrDeviceNotFound
	}
	highWater := int64(len(state.events))
	if bound == 0 {
		bound = highWater
	}
	events = make([]Event, 0, limit)
	for index := afterSeq; index < bound; index++ {
		event := state.events[index]
		if !filter.From.IsZero() && event.ObservedAt.Before(filter.From) {
			continue
		}
		if !filter.To.IsZero() && event.ObservedAt.After(filter.To) {
			continue
		}
		if len(events) < limit {
			events = append(events, cloneEvent(event))
			continue
		}
		// A match beyond the filled page means another page exists even if the
		// returned page is short due to non-matching rows.
		return events, bound, true, nil
	}
	return events, bound, false, nil
}

